111|    chunk.offset = ctx->bytes_read - 8;
112|
113|    chunk.length = read_u32(ctx->data);
114|
115|    memcpy(&chunk.type, ctx->data + 4, 4);
116|
117|    if(chunk.length > png_u32max) return SPNG_ECHUNK_SIZE;
118|
119|    ctx->cur_chunk_bytes_left = chunk.length;
120|
121|    ctx->cur_actual_crc = crc32(0, NULL, 0);
122|    ctx->cur_actual_crc = crc32(ctx->cur_actual_crc, chunk.type, 4);
123|
124|    memcpy(&ctx->current_chunk, &chunk, sizeof(struct spng_chunk));
125|
126|    return 0;
127|}
