213|static uint8_t paeth(uint8_t a, uint8_t b, uint8_t c)
214|{
215|    int16_t p = (int16_t)a + (int16_t)b - (int16_t)c;
216|    int16_t pa = abs(p - (int16_t)a);
217|    int16_t pb = abs(p - (int16_t)b);
218|    int16_t pc = abs(p - (int16_t)c);
219|
220|    if(pa <= pb && pa <= pc) return a;
221|    else if(pb <= pc) return b;
222|
223|    return c;
224|}
