226|static int defilter_scanline(const unsigned char *prev_scanline, unsigned char *scanline,
227|                             size_t scanline_width, uint8_t bytes_per_pixel)
228|{
229|    if(prev_scanline == NULL || scanline == NULL || scanline_width <= 1) return 1;
230|
231|    size_t i;
232|    uint8_t filter = 0;
233|    memcpy(&filter, scanline, 1);
234|
235|    if(filter > 4) return SPNG_EFILTER;
236|    if(filter == 0) return 0;
237|
238|#if defined(SPNG_OPTIMIZE_DEFILTER)
239|    if(filter == SPNG_FILTER_TYPE_UP) goto no_opt;
240|
241|    if(bytes_per_pixel == 4)
242|    {
243|        if(filter == SPNG_FILTER_TYPE_SUB)
244|            png_read_filter_row_sub4(scanline_width - 1, scanline + 1);
245|        else if(filter == SPNG_FILTER_TYPE_AVERAGE)
246|            png_read_filter_row_avg4(scanline_width - 1, scanline + 1, prev_scanline + 1);
247|        else if(filter == SPNG_FILTER_TYPE_PAETH)
248|            png_read_filter_row_paeth4(scanline_width - 1, scanline + 1, prev_scanline + 1);
249|
250|        return 0;
251|    }
252|    else if(bytes_per_pixel == 3)
253|    {
254|        if(filter == SPNG_FILTER_TYPE_SUB)
255|            png_read_filter_row_sub3(scanline_width - 1, scanline + 1);
256|        else if(filter == SPNG_FILTER_TYPE_AVERAGE)
257|            png_read_filter_row_avg3(scanline_width - 1, scanline + 1, prev_scanline + 1);
258|        else if(filter == SPNG_FILTER_TYPE_PAETH)
259|            png_read_filter_row_paeth3(scanline_width - 1, scanline + 1, prev_scanline + 1);
260|
261|        return 0;
262|    }
263|no_opt:
264|#endif
265|
266|    for(i=1; i < scanline_width; i++)
267|    {
268|        uint8_t x, a, b, c;
269|
270|        if(i > bytes_per_pixel)
271|        {
272|            memcpy(&a, scanline + i - bytes_per_pixel, 1);
273|            memcpy(&b, prev_scanline + i, 1);
274|            memcpy(&c, prev_scanline + i - bytes_per_pixel, 1);
275|        }
276|        else /* first pixel in row */
277|        {
278|            a = 0;
279|            memcpy(&b, prev_scanline + i, 1);
280|            c = 0;
281|        }
282|
283|        memcpy(&x, scanline + i, 1);
284|
285|        switch(filter)
286|        {
287|            case SPNG_FILTER_TYPE_SUB:
288|            {
289|                x = x + a;
290|                break;
291|            }
292|            case SPNG_FILTER_TYPE_UP:
293|            {
294|                x = x + b;
295|                break;
296|            }
297|            case SPNG_FILTER_TYPE_AVERAGE:
298|            {
299|                uint16_t avg = (a + b) / 2;
300|                x = x + avg;
301|                break;
302|            }
303|            case SPNG_FILTER_TYPE_PAETH:
304|            {
305|                x = x + paeth(a,b,c);
306|                break;
307|            }
308|        }
309|
310|        memcpy(scanline + i, &x, 1);
311|    }
312|
313|    return 0;
314|}
