316|/*
317|    Read and validate all critical and relevant ancillary chunks up to the first IDAT
318|    Returns zero and sets ctx->first_idat on success
319|*/
320|static int get_ancillary_data_first_idat(spng_ctx *ctx)
321|{
322|    if(ctx == NULL) return 1;
323|    if(ctx->data == NULL) return 1;
324|    if(!ctx->valid_state) return SPNG_EBADSTATE;
325|
326|    int ret;
327|    unsigned char *data;
328|    struct spng_chunk chunk;
329|
330|    chunk.offset = 8;
331|    chunk.length = 13;
332|    size_t sizeof_sig_ihdr = 29;
333|
334|    ret = read_data(ctx, sizeof_sig_ihdr);
335|    if(ret) return ret;
336|
337|    data = ctx->data;
338|
339|    uint8_t signature[8] = { 137, 80, 78, 71, 13, 10, 26, 10 };
340|    if(memcmp(data, signature, sizeof(signature))) return SPNG_ESIGNATURE;
341|
342|    chunk.length = read_u32(data + 8);
343|    memcpy(&chunk.type, data + 12, 4);
344|
345|    if(chunk.length != 13) return SPNG_EIHDR_SIZE;
346|    if(memcmp(chunk.type, type_ihdr, 4)) return SPNG_ENOIHDR;
347|
348|    ctx->cur_actual_crc = crc32(0, NULL, 0);
349|    ctx->cur_actual_crc = crc32(ctx->cur_actual_crc, data + 12, 17);
350|
351|    ctx->ihdr.width = read_u32(data + 16);
352|    ctx->ihdr.height = read_u32(data + 20);
353|    memcpy(&ctx->ihdr.bit_depth, data + 24, 1);
354|    memcpy(&ctx->ihdr.color_type, data + 25, 1);
355|    memcpy(&ctx->ihdr.compression_method, data + 26, 1);
356|    memcpy(&ctx->ihdr.filter_method, data + 27, 1);
357|    memcpy(&ctx->ihdr.interlace_method, data + 28, 1);
358|
359|    if(!ctx->max_width) ctx->max_width = png_u32max;
360|    if(!ctx->max_height) ctx->max_height = png_u32max;
361|
362|    ret = check_ihdr(&ctx->ihdr, ctx->max_width, ctx->max_height);
363|    if(ret) return ret;
364|
365|    ctx->file_ihdr = 1;
366|    ctx->stored_ihdr = 1;
367|
368|    while( !(ret = read_header(ctx)))
369|    {
370|        memcpy(&chunk, &ctx->current_chunk, sizeof(struct spng_chunk));
371|
372|        if(!memcmp(chunk.type, type_idat, 4))
373|        {
374|            memcpy(&ctx->first_idat, &chunk, sizeof(struct spng_chunk));
375|            return 0;
376|        }
377|
378|        ret = read_chunk_bytes(ctx, chunk.length);
379|        if(ret) return ret;
380|
381|        data = ctx->data;
382|
383|        /* Reserved bit must be zero */
384|        if( (chunk.type[2] & (1 << 5)) != 0) return SPNG_ECHUNK_TYPE;
385|        /* Ignore private chunks */
386|        if( (chunk.type[1] & (1 << 5)) != 0) continue;
387|
388|        if(is_critical_chunk(&chunk)) /* Critical chunk */
389|        {
390|            if(!memcmp(chunk.type, type_plte, 4))
391|            {
392|                if(chunk.length == 0) return SPNG_ECHUNK_SIZE;
393|                if(chunk.length % 3 != 0) return SPNG_ECHUNK_SIZE;
394|                if( (chunk.length / 3) > 256 ) return SPNG_ECHUNK_SIZE;
395|
396|                if(ctx->ihdr.color_type == 3)
397|                {
398|                    if(chunk.length / 3 > (1 << ctx->ihdr.bit_depth) ) return SPNG_ECHUNK_SIZE;
399|                }
400|
401|                ctx->plte.n_entries = chunk.length / 3;
402|
403|                size_t i;
404|                for(i=0; i < ctx->plte.n_entries; i++)
405|                {
406|                    memcpy(&ctx->plte.entries[i].red,   data + i * 3, 1);
407|                    memcpy(&ctx->plte.entries[i].green, data + i * 3 + 1, 1);
408|                    memcpy(&ctx->plte.entries[i].blue,  data + i * 3 + 2, 1);
409|                }
410|
411|                ctx->plte_offset = chunk.offset;
412|
413|                ctx->file_plte = 1;
414|            }
415|            else if(!memcmp(chunk.type, type_iend, 4)) return SPNG_ECHUNK_POS;
416|            else if(!memcmp(chunk.type, type_ihdr, 4)) return SPNG_ECHUNK_POS;
417|            else return SPNG_ECHUNK_UNKNOWN_CRITICAL;
418|        }
419|        else if(!memcmp(chunk.type, type_chrm, 4)) /* Ancillary chunks */
420|        {
421|            if(ctx->file_plte && chunk.offset > ctx->plte_offset) return SPNG_ECHUNK_POS;
422|            if(ctx->file_chrm) return SPNG_EDUP_CHRM;
423|
424|            if(chunk.length != 32) return SPNG_ECHUNK_SIZE;
425|
426|            ctx->chrm_int.white_point_x = read_u32(data);
427|            ctx->chrm_int.white_point_y = read_u32(data + 4);
428|            ctx->chrm_int.red_x = read_u32(data + 8);
429|            ctx->chrm_int.red_y = read_u32(data + 12);
430|            ctx->chrm_int.green_x = read_u32(data + 16);
431|            ctx->chrm_int.green_y = read_u32(data + 20);
432|            ctx->chrm_int.blue_x = read_u32(data + 24);
433|            ctx->chrm_int.blue_y = read_u32(data + 28);
434|
435|            if(check_chrm_int(&ctx->chrm_int)) return SPNG_ECHRM;
436|
437|            ctx->file_chrm = 1;
438|            ctx->stored_chrm = 1;
439|        }
440|        else if(!memcmp(chunk.type, type_gama, 4))
441|        {
442|            if(ctx->file_plte && chunk.offset > ctx->plte_offset) return SPNG_ECHUNK_POS;
443|            if(ctx->file_gama) return SPNG_EDUP_GAMA;
444|
445|            if(chunk.length != 4) return SPNG_ECHUNK_SIZE;
446|
447|            ctx->gama = read_u32(data);
448|
449|            if(ctx->gama > png_u32max) return SPNG_EGAMA;
450|
451|            ctx->file_gama = 1;
452|            ctx->stored_gama = 1;
453|        }
454|        else if(!memcmp(chunk.type, type_iccp, 4))
455|        {
456|            if(ctx->file_plte && chunk.offset > ctx->plte_offset) return SPNG_ECHUNK_POS;
457|            if(ctx->file_iccp) return SPNG_EDUP_ICCP;
458|            if(!chunk.length) return SPNG_ECHUNK_SIZE;
459|
460|            continue; /* XXX: https://gitlab.com/randy408/libspng/issues/31 */
461|        }
462|        else if(!memcmp(chunk.type, type_sbit, 4))
463|        {
464|            if(ctx->file_plte && chunk.offset > ctx->plte_offset) return SPNG_ECHUNK_POS;
465|            if(ctx->file_sbit) return SPNG_EDUP_SBIT;
466|
467|            if(ctx->ihdr.color_type == 0)
468|            {
469|                if(chunk.length != 1) return SPNG_ECHUNK_SIZE;
470|
471|                memcpy(&ctx->sbit.grayscale_bits, data, 1);
472|            }
473|            else if(ctx->ihdr.color_type == 2 || ctx->ihdr.color_type == 3)
474|            {
475|                if(chunk.length != 3) return SPNG_ECHUNK_SIZE;
476|
477|                memcpy(&ctx->sbit.red_bits, data, 1);
478|                memcpy(&ctx->sbit.green_bits, data + 1 , 1);
479|                memcpy(&ctx->sbit.blue_bits, data + 2, 1);
480|            }
481|            else if(ctx->ihdr.color_type == 4)
482|            {
483|                if(chunk.length != 2) return SPNG_ECHUNK_SIZE;
484|
485|                memcpy(&ctx->sbit.grayscale_bits, data, 1);
486|                memcpy(&ctx->sbit.alpha_bits, data + 1, 1);
487|            }
488|            else if(ctx->ihdr.color_type == 6)
489|            {
490|                if(chunk.length != 4) return SPNG_ECHUNK_SIZE;
491|
492|                memcpy(&ctx->sbit.red_bits, data, 1);
493|                memcpy(&ctx->sbit.green_bits, data + 1, 1);
494|                memcpy(&ctx->sbit.blue_bits, data + 2, 1);
495|                memcpy(&ctx->sbit.alpha_bits, data + 3, 1);
496|            }
497|
498|            if(check_sbit(&ctx->sbit, &ctx->ihdr)) return SPNG_ESBIT;
499|
500|            ctx->file_sbit = 1;
501|            ctx->stored_sbit = 1;
502|        }
503|        else if(!memcmp(chunk.type, type_srgb, 4))
504|        {
505|            if(ctx->file_plte && chunk.offset > ctx->plte_offset) return SPNG_ECHUNK_POS;
506|            if(ctx->file_srgb) return SPNG_EDUP_SRGB;
507|
508|            if(chunk.length != 1) return SPNG_ECHUNK_SIZE;
509|
510|            memcpy(&ctx->srgb_rendering_intent, data, 1);
511|
512|            if(ctx->srgb_rendering_intent > 3) return SPNG_ESRGB;
513|
514|            ctx->file_srgb = 1;
515|            ctx->stored_srgb = 1;
516|        }
517|        else if(!memcmp(chunk.type, type_bkgd, 4))
518|        {
519|            if(ctx->file_plte && chunk.offset < ctx->plte_offset) return SPNG_ECHUNK_POS;
520|            if(ctx->file_bkgd) return SPNG_EDUP_BKGD;
521|
522|            uint16_t mask = ~0;
523|            if(ctx->ihdr.bit_depth < 16) mask = (1 << ctx->ihdr.bit_depth) - 1;
524|
525|            if(ctx->ihdr.color_type == 0 || ctx->ihdr.color_type == 4)
526|            {
527|                if(chunk.length != 2) return SPNG_ECHUNK_SIZE;
528|
529|                ctx->bkgd.gray = read_u16(data) & mask;
530|            }
531|            else if(ctx->ihdr.color_type == 2 || ctx->ihdr.color_type == 6)
532|            {
533|                if(chunk.length != 6) return SPNG_ECHUNK_SIZE;
534|
535|                ctx->bkgd.red = read_u16(data) & mask;
536|                ctx->bkgd.green = read_u16(data + 2) & mask;
537|                ctx->bkgd.blue = read_u16(data + 4) & mask;
538|            }
539|            else if(ctx->ihdr.color_type == 3)
540|            {
541|                if(chunk.length != 1) return SPNG_ECHUNK_SIZE;
542|                if(!ctx->file_plte) return SPNG_EBKGD_NO_PLTE;
543|
544|                memcpy(&ctx->bkgd.plte_index, data, 1);
545|                if(ctx->bkgd.plte_index >= ctx->plte.n_entries) return SPNG_EBKGD_PLTE_IDX;
546|            }
547|
548|            ctx->file_bkgd = 1;
549|            ctx->stored_bkgd = 1;
550|        }
551|        else if(!memcmp(chunk.type, type_trns, 4))
552|        {
553|            if(ctx->file_plte && chunk.offset < ctx->plte_offset) return SPNG_ECHUNK_POS;
554|            if(ctx->file_trns) return SPNG_EDUP_TRNS;
555|            if(!chunk.length) return SPNG_ECHUNK_SIZE;
556|
557|            uint16_t mask = ~0;
558|            if(ctx->ihdr.bit_depth < 16) mask = (1 << ctx->ihdr.bit_depth) - 1;
559|
560|            if(ctx->ihdr.color_type == 0)
561|            {
562|                if(chunk.length != 2) return SPNG_ECHUNK_SIZE;
563|
564|                ctx->trns.gray = read_u16(data) & mask;
565|            }
566|            else if(ctx->ihdr.color_type == 2)
567|            {
568|                if(chunk.length != 6) return SPNG_ECHUNK_SIZE;
569|
570|                ctx->trns.red = read_u16(data) & mask;
571|                ctx->trns.green = read_u16(data + 2) & mask;
572|                ctx->trns.blue = read_u16(data + 4) & mask;
573|            }
574|            else if(ctx->ihdr.color_type == 3)
575|            {
576|                if(chunk.length > ctx->plte.n_entries) return SPNG_ECHUNK_SIZE;
577|                if(!ctx->file_plte) return SPNG_ETRNS_NO_PLTE;
578|
579|                size_t k;
580|                for(k=0; k < chunk.length; k++)
581|                {
582|                    memcpy(&ctx->trns.type3_alpha[k], data + k, 1);
583|                }
584|                ctx->trns.n_type3_entries = chunk.length;
585|            }
586|            else return SPNG_ETRNS_COLOR_TYPE;
587|
588|            ctx->file_trns = 1;
589|            ctx->stored_trns = 1;
590|        }
591|        else if(!memcmp(chunk.type, type_hist, 4))
592|        {
593|            if(!ctx->file_plte) return SPNG_EHIST_NO_PLTE;
594|            if(chunk.offset < ctx->plte_offset) return SPNG_ECHUNK_POS;
595|            if(ctx->file_hist) return SPNG_EDUP_HIST;
596|
597|            if( (chunk.length / 2) != (ctx->plte.n_entries) ) return SPNG_ECHUNK_SIZE;
598|
599|            size_t k;
600|            for(k=0; k < (chunk.length / 2); k++)
601|            {
602|                ctx->hist.frequency[k] = read_u16(data + k*2);
603|            }
604|
605|            ctx->file_hist = 1;
606|            ctx->stored_hist = 1;
607|        }
608|        else if(!memcmp(chunk.type, type_phys, 4))
609|        {
610|            if(ctx->file_phys) return SPNG_EDUP_PHYS;
611|
612|            if(chunk.length != 9) return SPNG_ECHUNK_SIZE;
613|
614|            ctx->phys.ppu_x = read_u32(data);
615|            ctx->phys.ppu_y = read_u32(data + 4);
616|            memcpy(&ctx->phys.unit_specifier, data + 8, 1);
617|
618|            if(check_phys(&ctx->phys)) return SPNG_EPHYS;
619|
620|            ctx->file_phys = 1;
621|            ctx->stored_phys = 1;
622|        }
623|        else if(!memcmp(chunk.type, type_splt, 4))
624|        {
625|            if(ctx->user_splt) continue; /* XXX: should check profile names for uniqueness */
626|            if(!chunk.length) return SPNG_ECHUNK_SIZE;
627|
628|            ctx->file_splt = 1;
629|
630|            if(!ctx->stored_splt)
631|            {
632|                ctx->n_splt = 1;
633|                ctx->splt_list = spng__calloc(ctx, 1, sizeof(struct spng_splt));
634|                if(ctx->splt_list == NULL) return SPNG_EMEM;
635|            }
636|            else
637|            {
638|                ctx->n_splt++;
639|                if(ctx->n_splt < 1) return SPNG_EOVERFLOW;
640|                if(sizeof(struct spng_splt) > SIZE_MAX / ctx->n_splt) return SPNG_EOVERFLOW;
641|
642|                void *buf = spng__realloc(ctx, ctx->splt_list, ctx->n_splt * sizeof(struct spng_splt));
643|                if(buf == NULL) return SPNG_EMEM;
644|                ctx->splt_list = buf;
645|                memset(&ctx->splt_list[ctx->n_splt - 1], 0, sizeof(struct spng_splt));
646|            }
647|
648|            uint32_t i = ctx->n_splt - 1;
649|
650|            size_t keyword_len = chunk.length > 80 ? 80 : chunk.length;
651|            char *keyword_nul = memchr(data, '\0', keyword_len);
652|            if(keyword_nul == NULL) return SPNG_ESPLT_NAME;
653|
654|            memcpy(&ctx->splt_list[i].name, data, keyword_len);
655|
656|            if(check_png_keyword(ctx->splt_list[i].name)) return SPNG_ESPLT_NAME;
657|
658|            keyword_len = strlen(ctx->splt_list[i].name);
659|
660|            if( (chunk.length - keyword_len - 1) ==  0) return SPNG_ECHUNK_SIZE;
661|
662|            memcpy(&ctx->splt_list[i].sample_depth, data + keyword_len + 1, 1);
663|
664|            if(ctx->n_splt > 1)
665|            {
666|                uint32_t j;
667|                for(j=0; j < i; j++)
668|                {
669|                    if(!strcmp(ctx->splt_list[j].name, ctx->splt_list[i].name)) return SPNG_ESPLT_DUP_NAME;
670|                }
671|            }
672|
673|            if(ctx->splt_list[i].sample_depth == 16)
674|            {
675|                if( (chunk.length - keyword_len - 2) % 10 != 0) return SPNG_ECHUNK_SIZE;
