909|/* Scale "sbits" significant bits in "sample" from "bit_depth" to "target"
910|
911|   "bit_depth" must be a valid PNG depth
912|   "sbits" must be less than or equal to "bit_depth"
913|   "target" must be between 1 and 16
914|*/
915|static uint16_t sample_to_target(uint16_t sample, uint8_t bit_depth, uint8_t sbits, uint8_t target)
916|{
917|    uint16_t sample_bits;
918|    int8_t shift_amount;
919|
920|    if(bit_depth == sbits)
921|    {
922|        if(target == sbits) return sample; /* no scaling */
923|    }/* bit_depth > sbits */
924|    else sample = sample >> (bit_depth - sbits); /* shift significant bits to bottom */
925|
926|    /* downscale */
927|    if(target < sbits) return sample >> (sbits - target);
928|
929|    /* upscale using left bit replication */
930|    shift_amount = target - sbits;
931|    sample_bits = sample;
932|    sample = 0;
933|
934|    while(shift_amount >= 0)
935|    {
936|        sample = sample | (sample_bits << shift_amount);
937|        shift_amount -= sbits;
938|    }
939|
940|    int8_t partial = shift_amount + (int8_t)sbits;
941|
942|    if(partial != 0) sample = sample | (sample_bits >> abs(shift_amount));
943|
944|    return sample;
