226|static int defilter_scanline(const unsigned char *prev_scanline, unsigned char *scanline,
227|                             size_t scanline_width, uint8_t bytes_per_pixel)
228|{
229|    if(prev_scanline == NULL || scanline == NULL || scanline_width <= 1) return 1;
