252|    else if(bytes_per_pixel == 3)
253|    {
254|        if(filter == SPNG_FILTER_TYPE_SUB)
255|            png_read_filter_row_sub3(scanline_width - 1, scanline + 1);
256|        else if(filter == SPNG_FILTER_TYPE_AVERAGE)
257|            png_read_filter_row_avg3(scanline_width - 1, scanline + 1, prev_scanline + 1);
258|        else if(filter == SPNG_FILTER_TYPE_PAETH)
259|            png_read_filter_row_paeth3(scanline_width - 1, scanline + 1, prev_scanline + 1);
260|
261|        return 0;
262|    }
263|no_opt:
264|#endif
265|
266|    for(i=1; i < scanline_width; i++)
267|    {
268|        uint8_t x, a, b, c;
269|
270|        if(i > bytes_per_pixel)
271|        {
272|            memcpy(&a, scanline + i - bytes_per_pixel, 1);
273|            memcpy(&b, prev_scanline + i, 1);
274|            memcpy(&c, prev_scanline + i - bytes_per_pixel, 1);
275|        }
