288|            {
289|                x = x + a;
290|                break;
291|            }
292|            case SPNG_FILTER_TYPE_UP:
293|            {
294|                x = x + b;
295|                break;
296|            }
297|            case SPNG_FILTER_TYPE_AVERAGE:
298|            {
